import{_ as r,l as d,o as a,c,v as o,p as i,x as t,d as n,i as s,S as E}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"音频 codec 与离散 token","description":"","frontmatter":{"title":"音频 codec 与离散 token","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/audio-codec-lm.md","filePath":"llm/audio-codec-lm.md","lastUpdated":1789023840000}'),p={name:"llm/audio-codec-lm.md"};function A(h,e,m,u,_,L){const l=d("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="音频-codec-与离散-token" tabindex="-1">音频 codec 与离散 token <a class="header-anchor" href="#音频-codec-与离散-token" aria-label="Permalink to &quot;音频 codec 与离散 token&quot;">​</a></h1><div class="epigraph"><p>神经编解码器先把波形变成码本下标，语言模型才把「听」写成预测下一个下标；码率与码本大小决定语音在词表里占多宽。</p><footer>—— 对照 SoundStream / EnCodec / DAC 一类神经音频编解码器，以及 AudioLM、VALL-E 将其当作语言符号</footer></div><p><a href="/llm/audio-lm">上一课</a> 把音频语言模型写成在混合词表上做 \\(p(z_t\\mid z_{\\lt t})\\)。本课补它默认已经存在的那一层：<strong>离散码从哪来</strong>。<a href="/llm/speech-tokenizer">语音 tokenizer</a> 讲过一般切分；这里钉的是 codec：残差向量量化（RVQ）多层码本、帧率、以及为何「能听懂」和「能还原波形」对码的要求不一致。后课的视频时序默认你会：音频侧已经是时间上均匀的离散序列，不是梅尔谱上的连续回归。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Audio LM 不能直接在 16 kHz 采样点上做 softmax：帧率太高，词表若按振幅量化又没有语音结构。ASR 用连续编码器 + 文本解码，得不到可回放的中间符号。神经音频 codec 提供第三条路：编码器把短时帧映到连续向量，RVQ 把它拆成 \\(Q\\) 层码本下标 \\(c_{1:Q}\\)，解码器从码重构波形。语言模型看见的是这些下标，不是波形。</p><p>缺口有两层。第一，码要多细才够「像语言」：太粗，音色与辅音丢失，LM 再强也合成含混；太细，帧率 × 层数把上下文打满，文本能力被音频符号淹没。第二，多层码之间有残差依赖：粗层管全局、细层管残差。若 LM 对 \\(Q\\) 层当独立词表乱序预测，等于忽略 codec 的生成顺序。VALL-E 把粗层自回归、细层非自回归，正是在认这个依赖。</p><h3 id="离散化损失不是语言模型损失" tabindex="-1">离散化损失不是语言模型损失 <a class="header-anchor" href="#离散化损失不是语言模型损失" aria-label="Permalink to &quot;离散化损失不是语言模型损失&quot;">​</a></h3><p>Codec 的训练目标是重构与感知（对抗、特征匹配），不是下一个 token。码本崩溃、使用率不均，会让某些下标几乎从不见面，LM 词表里出现死符号。反过来，LM 可以在崩溃的码上拟合出「听起来对的」统计，但解码器还原失败。两条损失必须分开验收：码级 perplexity 降了不等于 MOS 升了。<span class="marginnote">EnCodec / DAC 等把量化器写成 RVQ：第一层量化残差，第二层量化上一层误差。层间不是可交换的词表。把 \\(Q\\) 层拍扁成一个超大词表，会丢掉残差结构，也会让 softmax 大到 Cut CE 都头疼。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三种接入策略" tabindex="-1">三种接入策略 <a class="header-anchor" href="#三种接入策略" aria-label="Permalink to &quot;三种接入策略&quot;">​</a></h3><p>记帧率 \\(r\\)（如 50 Hz），每帧 \\(Q\\) 个码。一秒音频是 \\(rQ\\) 个离散符号。接入 LLM 的典型策略：</p><ul><li><strong>扁平交错</strong>：按时间展开，每帧依次写 \\(c_1,\\ldots,c_Q\\)，词表大小为各码本大小之和或并上文本词表。</li><li><strong>分层生成</strong>：先对 \\(\\{c_1^{(t)}\\}_t\\) 做语言模型，再条件粗码生成细码（VALL-E 式）。</li><li><strong>延迟图案 / 多头</strong>：同一 Transformer 步并行预测若干层，用延迟错开因果依赖。</li></ul><p>理解型 Audio LLM（听写、音频问答）可以不走 codec，而走连续音频编码器 + 连接器，类似 <a href="/llm/early-late-fusion">早融合</a> 的视觉塔。本课的 codec 路径是为了<strong>既能理解又能生成波形</strong>。两条路径不要在同一张架构图里画成一个块。</p>',13)),(a(),i(E,null,{default:t(()=>[s(l,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%B3%A2%E5%BD%A2%22%5D%20--%3E%20ENC%5B%22%E7%A5%9E%E7%BB%8F%20codec%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20ENC%20--%3E%20RVQ%5B%22RVQ%20%E5%A4%9A%E5%B1%82%E7%A0%81%E6%9C%AC%22%5D%0A%20%20RVQ%20--%3E%20LM%5B%22%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%E9%A2%84%E6%B5%8B%E7%A0%81%22%5D%0A%20%20LM%20--%3E%20DEC%5B%22codec%20%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20DEC%20--%3E%20W2%5B%22%E9%87%8D%E6%9E%84%E6%B3%A2%E5%BD%A2%22%5D%0A%20%20RVQ%20--%3E%20TXT%5B%22%E4%B8%8E%E6%96%87%E6%9C%AC%E8%AF%8D%E8%A1%A8%E4%BA%A4%E9%94%99%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RVQ 的第一层码往往已经能驱动可懂度，后续层修频谱细节与说话人。LM 若平均对待所有层，会把容量浪费在人耳不敏感的残差上，却仍可能漏掉第一层的音素错误。分层损失或对粗层给更高采样温度，是在承认感知上的不平等。</p><p>时间对齐上，codec 帧通常均匀；文本 token 不是均匀时间。交错训练时，「一秒语音对应多少文本 token」随语速变。位置编码若只按符号序号，语速信息丢失。需要时间戳、或把音频 RoPE 的时间分量按绝对秒来走，与视频课将遇到的「帧索引不是时间」是同一原则。</p><p><span class="marginnote">SoundStream、EnCodec、DAC 是编码器–量化–解码器；HuBERT / w2v-BERT 离散单元来自自监督聚类，重构波形要另接声码器。两者都能当 Audio LM 的符号，但「codec」一词应留给带可微或可训练解码器、能闭环回波形的系统。评测生成必须过解码器，不能只报码准确率。</span></p><h3 id="词表膨胀与文本污染" tabindex="-1">词表膨胀与文本污染 <a class="header-anchor" href="#词表膨胀与文本污染" aria-label="Permalink to &quot;词表膨胀与文本污染&quot;">​</a></h3><p>音频码并入 LLM 词表后，softmax 变宽，文本 perplexity 可能被拖累——稀有码的梯度噪声进共享层。缓解：分离音频头（只在音频位置上走音频 softmax）、或保持独立 codec 词表、用特殊切换 token 进入音频模式。共享一个巨大词表最简单，也最容易在纯文本基准上掉点。这是配比问题，不是「离散化是否优雅」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>低码率 codec 适合语义 LM（内容、转写），高码率适合保真 TTS。用 1.5 kbps 的码去训音乐生成，谐波细节不够；用 24 kbps 的码去训长音频理解，上下文会被码流撑爆。任务应先定感知预算再定 \\(r,Q\\)。流式场景还要看 codec 的 lookahead：为了量化一层而看未来几十毫秒，会把首包延迟写进产品。</p><p>离散扩散（后课）可以在码序列上做双向去噪，不强制自回归；但 codec 的层间残差依赖仍然在，扩散的前向加噪若把各层当独立比特打乱，会比 AR 更伤重构。Codec 选择约束生成器，不论生成器是 AR 还是扩散。</p><p><span class="marginnote">不要发明「某年某号 codec 论文」当唯一标准。工程上锁版本：同一条 LM 必须配对训练时用的解码器；换 EnCodec 带宽却不重训 LM，码本错位，生成会崩成噪声。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>神经 codec 把波形变成 RVQ 下标，Audio LM 预测这些下标再解码回放。</li><li>码率 × 层数是上下文税；粗层与细层不可当独立可交换词表。</li><li>理解可用连续编码器，生成回放必须走 codec 闭环。</li><li>音频词表并入 LLM 会污染文本 softmax，常用分头或模式切换隔离。</li><li>帧率均匀不等于与文本时间对齐；位置编码要能表达绝对时间。</li><li>出处：SoundStream / EnCodec / DAC；AudioLM、VALL-E 的码序列语言建模。</li></ul>',12))])}const C=r(p,[["render",A]]);export{k as __pageData,C as default};
